<script setup lang="ts">
import { onMounted, reactive } from 'vue';import { RouterLink } from 'vue-router';import OrderScenarioBar from '../components/OrderScenarioBar.vue';import OrderFulfillmentSubnav from '../components/OrderFulfillmentSubnav.vue';import { useOrderStore } from '../runtime/order-store';import type { CustomerReturnStatus } from '../types';import './order-views.css'
const store=useOrderStore();const filters=reactive({keyword:'',orderNo:'',status:''});const statusText:Record<CustomerReturnStatus,string>={'pending-review':'待审核',returned:'已退回',approved:'已审核',completed:'已完成',cancelled:'已取消'};const receiving={pending:'未收货',received:'已收货'};const refund={'not-created':'未退款',pending:'待退款',refunded:'已退款',rejected:'已拒绝','not-required':'无需退款'};const money=(v:number)=>`¥${(v/100).toFixed(2)}`;const search=()=>store.loadReturns({keyword:filters.keyword||undefined,orderNo:filters.orderNo||undefined,statuses:filters.status?[filters.status as CustomerReturnStatus]:undefined,page:1,pageSize:30});onMounted(()=>store.loadReturns())
</script>
<template><section class="order-page"><header class="order-header"><div><h1>客户退单</h1><p>退单、收货入库与退款三条状态独立追踪。</p></div><OrderScenarioBar :scenario="store.scenario" :role="store.actor.role" @scenario="store.setScenario($event).then(()=>store.loadReturns())" @role="store.setRole($event).then(()=>store.loadReturns())"/></header><OrderFulfillmentSubnav/><div class="order-panel order-filter"><label class="keyword">关键词<input v-model="filters.keyword" placeholder="退单号/客户/商品名称" @keyup.enter="search"></label><label>原订单号<input v-model="filters.orderNo"></label><label>退单状态<select v-model="filters.status"><option value="">全部</option><option v-for="(label,key) in statusText" :key="key" :value="key">{{label}}</option></select></label><button class="order-button" @click="search">查询</button></div><div class="order-toolbar"><span>共 {{store.returnResult.total}} 张退单</span><div><RouterLink v-if="['super-admin','salesperson'].includes(store.actor.role)" class="order-button primary" to="/orders/returns/new">新增退单</RouterLink></div></div><div v-if="store.error" class="order-state error"><strong>加载失败</strong><span>{{store.error}}</span></div><div v-else-if="store.loading" class="order-state">正在加载退单…</div><div v-else class="order-table-wrap"><table class="order-table return-table"><thead><tr><th>退单号</th><th>申请时间</th><th>客户</th><th>原订单</th><th class="order-money">退单金额</th><th>退单状态</th><th>收货状态</th><th>退款状态</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="row in store.returnResult.items" :key="row.value.id"><td><RouterLink :to="`/orders/returns/${row.value.id}`"><strong>{{row.value.returnNo}}</strong></RouterLink></td><td>{{row.value.createdAt}}</td><td>{{row.value.customerSnapshot.name}}</td><td>{{row.value.orderNoSnapshot}}</td><td class="order-money">{{row.amountsVisible?money(row.value.returnAmountCents):'已遮蔽'}}</td><td><span class="order-status">{{statusText[row.value.status]}}</span></td><td>{{receiving[row.value.receivingStatus]}}</td><td :class="{'return-danger':row.value.refundStatus==='pending'}">{{refund[row.value.refundStatus]}}</td><td>{{row.value.remark??'—'}}</td><td><RouterLink :to="`/orders/returns/${row.value.id}`">查看</RouterLink><RouterLink v-if="row.canEdit" class="order-row-link" :to="`/orders/returns/${row.value.id}/edit`">修改</RouterLink></td></tr><tr v-if="!store.returnResult.items.length"><td colspan="10" class="order-empty-cell">暂无客户退单</td></tr></tbody></table></div></section></template>
